sql:
SELECT Country
FROM singer
WHERE Age > 40 OR Age < 30;

SELECT StuID, weight
FROM Has_Pet
WHERE PetAge > 1;

SELECT Maker, FullName
FROM car_makers
WHERE Year = 1970;

SELECT Year, AVG(Weight), AVG(Horsepower) AS YearAverageWeight, AVG(Weight) AS YearAverageWeight
FROM cars_data
GROUP BY Year;

SELECT Location, COUNT(*) AS count
FROM shop
GROUP BY Location;

SELECT District
FROM shop
WHERE (Number_products < 3000) AND (Number_products > 10000);

SELECT Document_ID, Template_ID, Document_Description
FROM Documents
WHERE Document_Name = 'Robbin CV';

SELECT COUNT(*) AS Count
FROM Templates
WHERE Template_Type_Code = 'CV';

SELECT Hometown FROM teacher WHERE Hometown IN (
    SELECT Hometown FROM course_arrange
) AND Hometown IN (
    SELECT Hometown FROM course
);

SELECT first_name, birth_date
FROM players
WHERE country_code = 'US';

SELECT ranking_date, COUNT(ranking) AS total_tours
FROM rankings
GROUP BY ranking_date;

SELECT year, COUNT(*) AS matches_played
FROM matches
GROUP BY year;

SELECT name, result
FROM battle
WHERE bulgarian_commander != 'Boril';

SELECT Nationality, COUNT(*) AS Count
FROM people
GROUP BY Nationality;

SELECT MAX(GNP) AS LargestGNP, COUNT(*) AS TotalPeople
FROM country
WHERE Continent = 'Asia';

SELECT COUNT(*) AS total_languages
FROM countrylanguage
WHERE CountryCode = 'ARUBA';

SELECT professional_id, first_name, email_address
FROM Professionals
WHERE role_code = 'Veterenarian' AND charge_amount IS NULL;

SELECT Citizenship, COUNT(*) AS Number_of_Singers
FROM singer
GROUP BY Citizenship;
